import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"42、【益】 震下巽上","description":"子夏易傳 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"子夏易傳 - 42、【益】 震下巽上"},"headers":[],"relativePath":"classics/zixia/044.md","filePath":"classics/zixia/044.md"}'),i={name:"classics/zixia/044.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><p>卦辭：益，利有攸往，利涉大川。</p><p>彖曰：益，損上益下，民説無疆。自上下下，其道大光。利有攸往，中正有慶。利涉大川，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道與時偕行。</p><p>子夏：為上者其道下濟也，故損上之剛，分而下益於柔。自上下下者也。中正為主，益而得時，何往而不可哉。是以有慶也。動巽而木行也。乘於大川而無險也。益動而巽於人，日進而無疆也。天施而後地生，上益而後下奉其益，豈窮哉。益之無當，雖惠而不行也，故時與而後可也。</p><p>象曰：風雷，益。君子以見善，則遷有過，則改。</p><p>子夏：雷行而風從，益，其震也。見善則遷，有過則改，益莫大也。</p><p>初九，利用為大作，元吉無咎。</p><p>象曰：元吉無咎，下不厚事也。</p><p>子夏：益，損上益下者也。夫受上之益而豈徒哉，必有大功而可以當之矣。初以剛下為動之主，能堪也大事者。下者難處之地，非專厚之所，得其大吉，乃無咎也。</p><p>六二，或益之十朋之龜，弗克違，永貞吉。王用享於帝，吉。</p><p>象曰：或益之，自外來也。</p><p>子夏：柔以得位，受上之益，得中之道，能精意以奉五，通於人而信於神也，故外來非常之祐也。夫陰之所利，在於永貞，而二能盡之，其於吉也。雖訪諸十朋之，不能違也，長正之道，豈止於臣下哉。雖王用之而享於上帝吉也。</p><p>六三，益之，用凶事無咎。有孚中行，告公用圭。</p><p>象曰：益用凶事，固有之也。</p><p>子夏：柔處高位危，咎之道也。居危而受上之益，非其見危致命，堅志而固有其事則不免矣。五為施益之主，而已竭，信不敢自專，必中行以告之用圭以表之，乃可能行奉其中也。</p><p>六四，中行，告公從，利用為依遷國。</p><p>象曰：告公從，以益志也。</p><p>（原本闕傳）</p><p>九五，有孚惠心，勿問元吉，有孚惠我徳。</p><p>象曰：有孚惠心，勿問之矣。惠我徳，大得志也。</p><p>子夏：有中正之徳，當益之尊，信以令人，施以心惠，勿問之矣，乃大吉也。我信惠下，下益報之，上下交孚，治之至也，大得其志矣。</p><p>上九，莫益之，或擊之，立心勿恆，兇。</p><p>象曰：莫益之，偏辭也。或擊之，自外來也。</p><p>子夏：五以中正，人皆歸之，上九乘之，過求眾附，雖有其應，豈附之哉。獨自益之，人不益矣。不能修整立心，勿恆多求於人，人所忿也。益窮反損，故有外來而擊之者也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
